#include <bits/stdc++.h>
using namespace std;

struct IntStack {
    std::vector<int> data;
    int size;

    IntStack() : data(8), size(0) {}

    void push(int val) {
        if (size >= (int)data.size()) {
            data.resize(data.size() * 2);
        }
        data[size++] = val;
    }

    int get(int index) const {
        assert(index >= 0 && index < size);
        return data[index];
    }

    int getSize() const {
        return size;
    }
};

class NumberTheory {
public:
    struct Mod998 {
        long long modulus() const {
            return 998244353LL;
        }

        long long fact(int n, IntStack &factorials, IntStack &invFactorials) {
            while (factorials.getSize() <= n) {
                long long lastFact = factorials.get(factorials.getSize() - 1);
                factorials.push((int)((lastFact * factorials.getSize()) % modulus()));
            }
            return factorials.get(n);
        }

        long long fInv(int n, IntStack &factorials, IntStack &invFactorials) {
            int lastIdx = invFactorials.getSize() - 1;
            if (lastIdx < n) {
                std::vector<long long> invs(n - lastIdx);
                long long invFactN = mult(fact(n, factorials, invFactorials), 1LL);
                invs[0] = inv(invFactN, modulus());
                for (int i = 1; i < (int)invs.size(); i++) {
                    invs[i] = mult(invs[i - 1], n - i + 1, modulus());
                }
                for (int i = (int)invs.size() - 1; i >= 0; i--) {
                    invFactorials.push((int)invs[i]);
                }
            }
            return invFactorials.get(n);
        }

        long long paritySign(long long k) const {
            return (k & 1) ? modulus() - 1 : 1;
        }

        long long ncr(int n, int r, IntStack &factorials, IntStack &invFactorials) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n, factorials, invFactorials), mult(fInv(r, factorials, invFactorials), fInv(n - r, factorials, invFactorials)), modulus());
        }

        long long smallInv(int n, IntStack &factorials, IntStack &invFactorials) {
            return mult(fInv(n, factorials, invFactorials), fact(n - 1, factorials, invFactorials), modulus());
        }

        long long add(long long a, long long b, long long mod) const {
            long long sum = a + b;
            return sum >= mod ? sum - mod : sum;
        }

        long long mult(long long a, long long b, long long mod) const {
            return (a * b) % mod;
        }

        long long inv(long long a, long long mod) const {
            // Using Fermat's little theorem since mod is prime
            return powMod(a, mod - 2, mod);
        }

        long long powMod(long long base, long long exp, long long mod) const {
            long long result = 1;
            long long cur = base % mod;
            while (exp > 0) {
                if (exp & 1) result = (result * cur) % mod;
                cur = (cur * cur) % mod;
                exp >>= 1;
            }
            return result;
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;
    IntStack factorials, invFactorials;
    // Initialize factorials and invFactorials with 1
    factorials.push(1);
    invFactorials.push(1);

    long long modVal = mod.modulus();

    long long p = 1;
    long long phaseSize = 1;
    for (int i = 0; p != 0; i++) {
        long long numerator = p;
        long long denominatorInv = mod.smallInv(n + m - i, factorials, invFactorials);
        long long multRes = mod.mult(numerator, denominatorInv, modVal);
        p = multRes;
        phaseSize = mod.add(phaseSize, p, modVal);
        if (i >= n) break; // To prevent infinite loop if p becomes 0 early
    }

    long long total = 0;
    for (int k = 1; k <= n; k++) {
        long long term = 1;
        term = mod.mult(term, mod.paritySign(k + 1), modVal);
        term = mod.mult(term, mod.ncr(n, k, factorials, invFactorials), modVal);
        term = mod.mult(term, m + k, modVal);
        term = mod.mult(term, mod.smallInv(k, factorials, invFactorials), modVal);
        term = mod.mult(term, phaseSize, modVal);
        total = mod.add(total, term, modVal);
    }

    cout << total << "\n";

    return 0;
}

